function solve(s, p) {
  const res = [];
  const m = p.length;
  if (m > s.length) return res;
  const target = p.split('').sort().join('');
  for (let i = 0; i + m <= s.length; i++) {
    const window = s.slice(i, i + m).split('').sort().join('');
    if (window === target) res.push(i);
  }
  return res;
}

function solve(s, p) {
  const res = [];
  const n = s.length;
  const m = p.length;
  if (m > n) return res;
  const need = new Array(26).fill(0);
  const have = new Array(26).fill(0);
  for (let i = 0; i < m; i++) need[p.charCodeAt(i) - 97]++;
  let matches = 0;
  for (let c = 0; c < 26; c++) if (need[c] === 0) matches++;
  for (let i = 0; i < n; i++) {
    const ci = s.charCodeAt(i) - 97;
    have[ci]++;
    if (have[ci] === need[ci]) matches++;
    else if (have[ci] === need[ci] + 1) matches--;
    if (i >= m) {
      const cj = s.charCodeAt(i - m) - 97;
      have[cj]--;
      if (have[cj] === need[cj]) matches++;
      else if (have[cj] === need[cj] - 1) matches--;
    }
    if (matches === 26) res.push(i - m + 1);
  }
  return res;
}
